const MOD = 1000000007;

function solve() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    if (input.length < 2) return;
    const w = parseInt(input[0], 10);
    const h = parseInt(input[1], 10);

    const Nx = w + 1;
    const Ny = h + 1;
    const totalPoints = Nx * Ny;

    // Total ordered triples of distinct points
    let total_triples = totalPoints % MOD;
    total_triples = (total_triples * ((totalPoints - 1) % MOD)) % MOD;
    total_triples = (total_triples * ((totalPoints - 2) % MOD)) % MOD;

    // Subtract collinear triples (ordered)
    // Vertical lines
    let vertical = Nx % MOD;
    vertical = (vertical * (Ny % MOD)) % MOD;
    vertical = (vertical * ((Ny - 1) % MOD)) % MOD;
    vertical = (vertical * ((Ny - 2) % MOD)) % MOD;

    // Horizontal lines
    let horizontal = Ny % MOD;
    horizontal = (horizontal * (Nx % MOD)) % MOD;
    horizontal = (horizontal * ((Nx - 1) % MOD)) % MOD;
    horizontal = (horizontal * ((Nx - 2) % MOD)) % MOD;

    // Diagonal lines
    let diagSum = 0;
    const maxW = w;
    const maxH = h;
    for (let dx = 1; dx <= maxW; dx++) {
        for (let dy = 1; dy <= maxH; dy++) {
            const g = gcd(dx, dy);
            if (g < 2) continue;
            const k = g - 1;
            const term = k % MOD;
            const term2 = (k - 1) % MOD;
            const term3 = (k + 1) % MOD;
            const countLines = ((w - dx + 1) % MOD) * ((h - dy + 1) % MOD) % MOD;
            const contrib = (2 * term % MOD) * term2 % MOD * term3 % MOD * countLines % MOD;
            diagSum = (diagSum + contrib) % MOD;
        }
    }

    let collinear = (vertical + horizontal) % MOD;
    collinear = (collinear + diagSum) % MOD;

    let triangles = (total_triples - collinear + MOD) % MOD;

    // Compute E = number of triples with D even
    // D = (x2-x1)*(y3-y1) - (x3-x1)*(y2-y1)
    // We fix P1 at origin. Dx = x2*y3 - x3*y2.
    // Count types of points in grid relative to an origin.
    // Since grid is not symmetric around origin for all P1, we sum over all P1.
    // But counts of parity types (x%2, y%2) only depend on available ranges.
    // Let cnt[p][q] be number of points (dx, dy) with dx%2=p, dy%2=q relative to a fixed P1.
    // Sum over all P1 of F(cnt) where F counts ordered pairs (P2,P3) distinct with even D.
    // This can be aggregated by counting how many P1 yield each specific cnt configuration.

    // Count points in full grid by parity
    const c = [[0, 0], [0, 0]];
    for (let x = 0; x <= w; x++) {
        for (let y = 0; y <= h; y++) {
            c[x & 1][y & 1]++;
        }
    }

    // For each possible P1 parity (px, py), the grid of other points relative to P1
    // has counts based on the full grid counts shifted by parity.
    // Number of points P1 with parity (px, py) is c[px][py].
    // For a fixed P1 at (x1,y1) with parity (px, py):
    // Point (x,y) has relative parity ( (x-x1)%2, (y-y1)%2 ) = ( (x%2)^px, (y%2)^py ) assuming mod 2 addition is XOR.
    // Let c_full[p][q] be total points with parity (p,q).
    // For fixed P1(px, py), count of other points with relative parity (a,b) is c_full[a^px][b^py] minus 1 if (a,b)==(0,0).

    let totalEven = 0;

    for (let px = 0; px < 2; px++) {
        for (let py = 0; py < 2; py++) {
            const num_P1 = c[px][py];
            if (num_P1 === 0) continue;

            // cnt[a][b] for relative vectors from P1
            const cnt = [[0, 0], [0, 0]];
            for (let a = 0; a < 2; a++) {
                for (let b = 0; b < 2; b++) {
                    cnt[a][b] = c[a ^ px][b ^ py];
                }
            }
            // Subtract P1 itself from (0,0) relative
            cnt[0][0]--;

            // Count ordered pairs (v2, v3) distinct from these counts such that cross product is even.
            // v = (x,y) mod 2. Cross = x2*y3 - x3*y2 mod 2.
            // Possible non-zero vectors: (1,0), (0,1), (1,1).
            // Cross products mod 2:
            // (1,0) x (0,1) = 1
            // (1,0) x (1,1) = 1
            // (0,1) x (1,0) = 1
            // (0,1) x (1,1) = 1
            // (1,1) x (1,0) = 1
            // (1,1) x (0,1) = 1
            // All others (same vector, or involving (0,0)) give 0.

            // Let c1 = cnt[1][0], c2 = cnt[0][1], c3 = cnt[1][1], c0 = cnt[0][0].
            // Total ordered pairs distinct = T * (T-1) where T = c0+c1+c2+c3.
            // Pairs with odd cross product:
            // (1,0) with (0,1): c1 * c2
            // (0,1) with (1,0): c2 * c1
            // (1,0) with (1,1): c1 * c3
            // (1,1) with (1,0): c3 * c1
            // (0,1) with (1,1): c2 * c3
            // (1,1) with (0,1): c3 * c2
            // Total odd = 2*(c1*c2 + c1*c3 + c2*c3)

            const c0 = cnt[0][0];
            const c1 = cnt[1][0];
            const c2 = cnt[0][1];
            const c3 = cnt[1][1];

            const T = (c0 + c1 + c2 + c3) % MOD;
            const totalPairs = T * ((T - 1 + MOD) % MOD) % MOD;

            let oddPairs = 0;
            oddPairs = (oddPairs + 2 * (c1 % MOD) * (c2 % MOD)) % MOD;
            oddPairs = (oddPairs + 2 * (c1 % MOD) * (c3 % MOD)) % MOD;
            oddPairs = (oddPairs + 2 * (c2 % MOD) * (c3 % MOD)) % MOD;

            const evenPairs = (totalPairs - oddPairs + MOD) % MOD;

            totalEven = (totalEven + num_P1 % MOD * evenPairs) % MOD;
        }
    }

    // E = totalEven. Number of ordered triples with integer area (D even).
    // Number with integer area = E.
    // Number with non-integer area = triangles - E.
    // We need number of non-degenerate triangles with integer area = E - collinear.
    // Note: Collinear triples have D=0 (even), so they are included in E.

    const answer = (totalEven - collinear + MOD) % MOD;

    console.log(answer);
}

function gcd(a, b) {
    while (b) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

solve();
